      "path": "skillcorpus_plugin/engine-typescript/src/gate.ts",
      "content": "/**\n * Relevance gate: an LLM pass that drops candidates this agent cannot run.\n *\n * Fusion ranks by position, so a source's best hit reaches the shortlist\n * however weakly it matched. This is where those go. The prompt also carries\n * an environment check that ranking cannot do at all: a skill whose body\n * assumes a vendor API, a `{baseDir}` placeholder, or a slash dispatcher is\n * unusable here no matter how well it matches the words, and injecting it\n * costs the turn context and sends the model down a path that dead-ends.\n *\n * Every failure keeps the top-ranked candidates rather than dropping to none.\n * An empty list is a decision the model is asked to make explicitly; it is\n * never the result of the gate itself breaking.\n *\n * @module\n */\n\nimport { bounded } from './deadline.js'\nimport { extractJsonObject } from './replies.js'\nimport type { RouterHit } from './types.js'\n\n/** Characters of body shown per candidate. Enough to judge, cheap to send. */\nconst BODY_EXCERPT_CHARS = 300\n\n/** How the gate reaches a model. Implemented by the plugin over `ctx.llm`. */\nexport interface GateModel {\n  complete(prompt: string, options: { signal?: AbortSignal | undefined }): Promise<string>\n}\n\n/** Selection bounds and the deadline for one gate call. */\nexport interface GateOptions {\n  /** Upper bound on selections. The model may return fewer, including none. */\n  readonly maxSelect?: number\n  /** Candidates kept when the gate cannot answer. */\n  readonly fallbackTopK?: number\n  /** Deadline for the call. This runs before the model replies to the user. */\n  readonly timeoutMs?: number\n}\n\n/** The relevance and executability gate, backed by one model call. */\nexport class LLMGateFilter {\n  private readonly model: GateModel\n  private readonly maxSelect: number\n  private readonly fallbackTopK: number\n  private readonly timeoutMs: number\n\n  constructor(model: GateModel, options: GateOptions = {}) {\n    this.model = model\n    this.maxSelect = options.maxSelect ?? 2\n    this.fallbackTopK = options.fallbackTopK ?? this.maxSelect\n    this.timeoutMs = options.timeoutMs ?? 20_000\n  }\n\n  /**\n   * Narrow `candidates` to the skills worth injecting for `task`.\n   *\n   * `availableTools` enables the environment check; without it the gate still\n   * judges relevance. Returns the top `fallbackTopK` candidates on timeout,\n   * transport failure, or an unparseable reply — a broken gate degrades to\n   * unfiltered retrieval rather than to silence.\n   *\n   * @param task - the user's words, unrewritten: the gate judges the real ask.\n   * @param candidates - the fused pool, best first.\n   * @param availableTools - tools this agent can call, enabling the hard rule.\n   * @param signal - aborts the call when the turn is cancelled.\n   * @returns the kept candidates, at most `maxSelect`, possibly empty.\n   */\n  async filter(\n    task: string,\n    candidates: readonly RouterHit[],\n    availableTools?: readonly string[],\n    signal?: AbortSignal,\n  ): Promise<RouterHit[]> {\n    if (candidates.length === 0) return []\n    const { catalog, byId } = buildCatalog(candidates)\n    const prompt = this.buildPrompt(task, catalog, availableTools)\n\n    let content: string\n    try {\n      content = await bounded(\n        s => this.model.complete(prompt, { signal: s }),\n        this.timeoutMs,\n        signal,\n      )\n    } catch {\n      return candidates.slice(0, this.fallbackTopK)\n    }\n\n    let selectedIds: string[]\n    try {\n      selectedIds = parseResponse(content)\n    } catch {\n      return candidates.slice(0, this.fallbackTopK)\n    }\n\n    const selected: RouterHit[] = []\n    for (const id of selectedIds.slice(0, this.maxSelect)) {\n      const hit = byId.get(id)\n      if (hit) selected.push(hit)\n    }\n    return selected\n  }\n\n  private buildPrompt(\n    task: string,\n    catalog: string,\n    availableTools?: readonly string[],\n  ): string {\n    let toolsBlock = ''\n    if (availableTools && availableTools.length > 0) {\n      const names = [...new Set(availableTools)].sort().join(', ')\n      toolsBlock =\n        '# Agent Tools\\n\\n' +\n        `The agent's ONLY available tools are: ${names}.\\n\\n` +\n        '**Hard rule**: a skill is NOT relevant if its workflow ' +\n        'requires any tool, file, or environment that the agent ' +\n        'lacks. Inspect EACH candidate\\'s body excerpt and ' +\n        'exclude it if you see any of:\\n' +\n        '- A specific external API / SDK / vendor ' +\n        '(e.g. ``nyne-deep-research``, ``musicbrainz``, ' +\n        '``bandcamp``, ``-api`` suffix, vendor wrapper).\\n' +\n        '- Environment placeholders or paths that won\\'t exist ' +\n        'in this runtime: ``${CLAUDE_PLUGIN_ROOT}``, ' +\n        '``{baseDir}``, ``{overrides}``, ``.aiwg/``, ``${SKILL_HOME}``, ' +\n        '``$ARGUMENTS`` as a slot, references to ' +\n        '``${...}`` template variables.\\n' +\n        '- Slash-command triggers (e.g. ``/research-query``) — ' +\n        'the agent has no slash dispatcher.\\n' +\n        '- ``Parent agent:`` style multi-agent framework ' +\n        'assumptions, or references to other SKILL.md files ' +\n        'under unspecified directories.\\n' +\n        '- Agent personas, role-play, creative writing, content ' +\n        'generation — these are not research procedures.\\n\\n' +\n        '**Only include** skills whose body describes a ' +\n        'self-contained procedure that the agent can execute ' +\n        'with just the listed tools (e.g. query-writing ' +\n        'strategies, verification workflows, ' +\n        'search-result interpretation).\\n\\n'\n    }\n    return (\n      'You are a skill selector for an autonomous agent.\\n\\n' +\n      `# Task\\n\\n${task}\\n\\n` +\n      toolsBlock +\n      `# Candidate Skills\\n\\n${catalog}\\n\\n` +\n      '# Instructions\\n\\n' +\n      '1. **Plan**: briefly think about what the task requires ' +\n      'and which sequence of available-tool calls would achieve it.\\n' +\n      '2. **Filter**: for EACH candidate skill, ask ' +\n      '\"can the agent execute this skill\\'s workflow using only the ' +\n      'available tools above?\" If no, drop it — no matter how ' +\n      'topically relevant.\\n' +\n      '3. **Match**: among the survivors, a skill is relevant ONLY ' +\n      'if it provides a procedure or strategy directly useful for ' +\n      'a core part of your plan. Vague topical overlap is not enough.\\n' +\n      `4. **Decide**: select AT MOST ${this.maxSelect} skill(s). ` +\n      'If no skill survives both the tool check and the relevance ' +\n      'check, you MUST return an empty list. Selecting an ' +\n      'irrelevant or unexecutable skill is strictly worse than ' +\n      'selecting none.\\n\\n' +\n      'Return ONLY a JSON object on a single line:\\n' +\n      '{\"plan\": \"1-sentence plan\", \"skills\": [\"qualified_id_1\"]}\\n\\n' +\n      'Or when nothing applies: {\"plan\": \"...\", \"skills\": []}\\n\\n' +\n      'Use the EXACT qualified_id strings from the candidate list above.'\n    )\n  }\n}\n\nfunction buildCatalog(candidates: readonly RouterHit[]): {\n  catalog: string\n  byId: Map<string, RouterHit>\n} {\n  const lines: string[] = []\n  const byId = new Map<string, RouterHit>()\n  for (const h of candidates) {\n    const sid = h.qualifiedId\n    let desc = ((h.meta.description as string | undefined) ?? '').trim().replace(/\\n/g, ' ')\n    if (!desc) desc = '(no description)'\n    if (desc.length > 200) desc = `${desc.slice(0, 197)}...`\n    const body = h.content.trim()\n    const excerpt = body.split(/\\s+/).join(' ').slice(0, BODY_EXCERPT_CHARS) || '(no body)'\n    lines.push(`- ${sid}: ${desc}\\n  Body excerpt: ${excerpt}`)\n    byId.set(sid, h)\n  }\n  return { catalog: lines.join('\\n'), byId }\n}\n\n/**\n * Pull the selection out of a model reply.\n *\n * Tolerates a reasoning block and a fenced or bare JSON object, because models\n * asked for \"only JSON\" routinely send one anyway. Throws when no object with\n * a `skills` array survives, which the caller turns into the unfiltered\n * fallback.\n */\nfunction parseResponse(content: string): string[] {\n  const data = extractJsonObject(content)\n  if (data === undefined) throw new Error('no JSON object in reply')\n  const skills = data.skills\n  if (!Array.isArray(skills)) throw new Error(\"missing 'skills' array\")\n  return skills.filter((s): s is string => typeof s === 'string' && s.length > 0)\n}\n\n"
    },
    {
      "path": "skillcorpus_plugin/engine-typescript/src/index.ts",
      "content": "/**\n * Per-turn skill retrieval: search on what the user just asked, inject what\n * fits.\n *\n * `dsh-tool-skill` publishes a catalog of every skill and lets the model load\n * one by name. This does the opposite: it searches local and remote sources\n * against the current message and puts the matching skill bodies straight in\n * front of the model, which needs no tool call and no name it has to already\n * know. The two are alternatives — running both publishes the same skills\n * twice — so a deployment picking this one disables `dsh-tool-skill`.\n *\n * Retrieval runs on `agent/pre-step`, before the model is called, and never\n * throws: a failed source or a slow catalog costs the turn its skills and\n * nothing else.\n *\n * @module @deepseek-ai/dsh-skill-search\n */\n\nimport { mkdirSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport type { Agent, PreStepDecision } from '@deepseek-ai/dsh-agent'\nimport { BlockAssembler, createUserMessage } from '@deepseek-ai/dsh-llm'\nimport type { FinishReason, GenerateOptions } from '@deepseek-ai/dsh-llm'\nimport type { UserMessage } from '@deepseek-ai/dsh-session'\n// Declaration-merges the optional `tools` service this reads through `ctx.get`.\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { SkillSearchEngine } from './engine.js'\nimport type { SkillSource } from './types.js'\nimport { LLMGateFilter } from './gate.js'\nimport { HubSkillSource, SkillHubClient } from './hub-source.js'\nimport { LocalSkillSource } from './local-source.js'\nimport { scanDirs, sharedSkillsDir } from './shared.js'\nimport { MarketplaceClient, MarketplaceSkillSource } from './marketplace-source.js'\nimport { QueryRewriter } from './rewriter.js'\n\nexport const name = 'skill-search'\nexport const inject = ['agents', 'llm']\n\nexport * from './types.js'\nexport { SkillSearchEngine } from './engine.js'\nexport type {\n  EngineOptions, EngineParts, RetrieveOptions, SourceDiagnostic, SourceDiagnosticStage,\n} from './engine.js'\nexport { LLMGateFilter } from './gate.js'\nexport { HubSkillSource, SkillHubClient } from './hub-source.js'\nexport { LocalSkillSource } from './local-source.js'\nexport { MarketplaceClient, MarketplaceSkillSource } from './marketplace-source.js'\nexport type { MarketplaceItem, MarketplaceKind } from './marketplace-source.js'\nexport { QueryRewriter } from './rewriter.js'\nexport { checkKeywordRelevance, queryTerms } from './relevance.js'\nexport { BM25Okapi, tokenize } from './bm25.js'\nexport { RRF_K, rrfMergeWeighted } from './fusion.js'\nexport { resolveRefs } from './refs.js'\n\n/** Per-turn skill retrieval configuration. */\nexport interface Config {\n  /** Directories scanned for `SKILL.md`. Relative paths resolve against cwd. */\n  skillsDirs?: string[]\n  shareSkills?: boolean\n  /** Remote catalog base URL. Empty disables the remote source. */\n  hubEndpoint?: string\n  /** Bearer token the catalog requires, if any. */\n  hubApiKey?: string\n  /** ClawHub API base URL. Empty disables this source. */\n  clawhubEndpoint?: string\n  /** skillhub.cn API base URL. Empty disables this source. */\n  skillhubCnEndpoint?: string\n  /**\n   * Where extracted bundles live. Outside every scanned skills directory,\n   * or a downloaded skill reappears as a local one on the next scan.\n   */\n  bundleCacheDir?: string\n  /** Per-request deadline for the catalog, search and body fetch alike. */\n  /**\n   * Index skill bodies alongside name and description. Off by default:\n   * the description is what the format asks authors to write the trigger\n   * conditions into, and it is what the gate reads.\n   */\n  indexBody?: boolean\n\n  /**\n   * Clean the query before searching. On by default: since it lost the\n   * power to veto retrieval it can only sharpen a match, never remove one.\n   * Requires `provider` and `model`.\n   */\n  rewrite?: boolean\n\n  /**\n   * Let a model drop candidates before they reach the prompt.\n   *\n   * Unset means \"on when `hubEndpoint` is configured\". The gate is told to\n   * reject when unsure: a curated local directory is better served by\n   * ranking alone, while a catalog of unvetted skills needs the check for\n   * whether this agent even has the tools a skill calls for. An explicit\n   * value is always honoured. Requires `provider` and `model`.\n   */\n  gate?: boolean\n\n  hubTimeoutMs?: number\n  /**\n   * Drop catalog entries whose safety score falls below this. Only bites on\n   * catalogs that put per-skill safety in the search payload.\n   */\n  hubMinSafety?: number\n  /** Fusion weight for local skills, which are curated and so outrank. */\n  weightLocal?: number\n  /** Fusion weight for catalog skills. */\n  weightHub?: number\n  /** Skills injected per turn. */\n  topK?: number\n  /** Candidates the gate judges before selecting. */\n  gatePool?: number\n  /** Upper bound on what the gate keeps. */\n  maxSelect?: number\n  /**\n   * Registered provider route for the rewriter and the gate. Required with\n   * `model`; either one alone fails at load.\n   */\n  provider?: string\n  /**\n   * Model for the rewriter and the gate. Unset runs retrieval unfiltered,\n   * which lets a weak best-hit from any source reach the prompt: fusion ranks\n   * by position, and removing those is the gate's job.\n   */\n  model?: string\n  /**\n   * Deadline for the rewrite, the turn's first model call. Tight because\n   * it runs before the gate and before the model answers: a stalled\n   * rewriter must degrade to searching the raw query, not hold the turn.\n   */\n  rewriteTimeoutMs?: number\n  /** Deadline for the gate, which runs before the user sees a reply. */\n  gateTimeoutMs?: number\n  /**\n   * Rewrite `{baseDir}` and bundled-file links in selected bodies to absolute\n   * paths. Turn off when the agent does not share a filesystem with the\n   * skills it retrieves.\n   */\n  resolveRefs?: boolean\n  /** Expand PathGuard placeholders in trusted skill bodies. Off by default. */\n  resolvePlaceholders?: boolean\n  /**\n   * How skills reach the agent.\n   *\n   * - `on_demand` (the default) registers a `skill_search` tool and lets the\n   *   agent decide when it needs one. A long task pays for retrieval at the\n   *   step that needs it and nothing on the turns that do not.\n   * - `auto` searches every turn and injects what it finds, surfacing\n   *   capability the agent did not know to ask for at the cost of running on\n   *   every turn regardless.\n   *\n   * Exclusive: running both would search twice a turn and put the same skill\n   * in front of the model from two directions.\n   */\n  mode?: 'on_demand' | 'auto'\n}\n\nexport const Config: z<Config> = z.object({\n  skillsDirs: z.array(z.string()).default(['.dsh/skills']),\n  // Join the cross-host shared library. Off stops this host reading the\n  // others; to stop the others reading this one, set `enabled: false` on\n  // its line in the shared registry.json.\n  shareSkills: z.boolean().default(true),\n  hubEndpoint: z.string().default('https://skillhub.evermind.ai'),\n  hubApiKey: z.string().default(''),\n  clawhubEndpoint: z.string().default('https://clawhub.ai'),\n  skillhubCnEndpoint: z.string().default('https://api.skillhub.cn'),\n  bundleCacheDir: z.string().default(''),\n  indexBody: z.boolean().default(false),\n  rewrite: z.boolean().default(true),\n  gate: z.boolean(),\n  hubTimeoutMs: z.number().default(5000),\n  hubMinSafety: z.number().default(0.7),\n  weightLocal: z.number().default(1.0),\n  weightHub: z.number().default(0.85),\n  topK: z.number().default(2),\n  gatePool: z.number().default(10),\n  maxSelect: z.number().default(2),\n  provider: z.string().default(''),\n  model: z.string().default(''),\n  rewriteTimeoutMs: z.number().default(5_000),\n  gateTimeoutMs: z.number().default(20_000),\n  resolveRefs: z.boolean().default(true),\n  resolvePlaceholders: z.boolean().default(false),\n  // A union, not `z.string()`: the branch below reads `!== 'auto'`, so a\n  // plain string schema turns `mode: \"atuo\"` into a silent downgrade to\n  // on-demand — the deployment asks for auto and never learns it did not get\n  // it. Narrowed, the loader rejects the typo instead.\n  mode: z.union([z.const('on_demand'), z.const('auto')]).default('on_demand'),\n})\n\n/** Marks the messages this plugin publishes. */\nexport interface SkillSearchSource {\n  readonly kind: 'skill-search'\n  /** Injected skill bodies are instructions for the model to follow. */\n  readonly form: 'instructions'\n  /**\n   * The ids injected this turn, so a transcript consumer reads what the model\n   * was shown from metadata instead of re-parsing the model-facing text.\n   */\n  readonly skillIds: readonly string[]\n}\n\ndeclare module '@deepseek-ai/dsh-llm' {\n  interface MessageSourceMap {\n    /** Skills retrieved for the current turn and injected before the step. */\n    'skill-search': SkillSearchSource\n  }\n}\n\n/**\n * What the agent reads to decide whether to search.\n *\n * In auto mode a weak block costs a turn some tokens. Here this text *is* the\n * discovery mechanism: an agent only searches if the description told it to.\n * The in-house-convention clause is not padding — measured on a real host, a\n * question about an internal template went unanswered until it was named.\n */\n// Joined with newlines, not spaces: the empty strings above are blank lines,\n// and the dashes are a list. `.join(' ')` flattened the whole thing into one\n// paragraph — the model still called the tool, but the shape the text was\n// written in never reached it.\nconst SKILL_SEARCH_DESCRIPTION = [\n  'Search the skill library for a procedure that fits the task at hand, and',\n  'get back the matching skills in full.',\n  '',\n  'A skill is a written workflow for a specific job — filling PDF forms,',\n  'building a slide deck, migrating a schema — including the exact commands,',\n  'files, and in-house conventions it needs.',\n  '',\n  'Reach for it when:',\n  '- a task needs a multi-step procedure you would otherwise improvise;',\n  '- a task names a format, tool, or workflow you would have to guess at;',\n  '- a question asks about an internal convention, template, standard, or',\n  '  \"our\" way of doing something — a skill is where those are written down,',\n  '  so searching here comes before answering that you do not know.',\n  '',\n  'Search with the words the task actually uses; the query is matched against',\n  'skill names and descriptions. Returns nothing when the library has no fit,',\n  'which is a normal answer and means: proceed on your own.',\n].join('\\n')\n\n\nexport function apply(ctx: Context, config: Config = {}): void {\n  const cfg = Config(config)\n  const engine = buildEngine(ctx, cfg)\n  if (!engine.enabled) {\n    ctx.logger('skill-search').info('no sources configured; retrieval is off')\n    return\n  }\n\n  if ((cfg.mode ?? 'on_demand') !== 'auto') {\n    // On demand. No `agent/pre-step` hook: injecting on every turn is the\n    // other mode, and running both would search twice for one turn.\n    //\n    // `ctx.inject` rather than adding `'tools'` to the module's `inject`\n    // array: entries in that array are *required* services, so listing it\n    // there would stop the plugin loading at all — auto mode included — on a\n    // composition that mounts no tool service. Here the dependency is scoped\n    // to the mode that actually needs it.\n    ctx.inject(['tools'], (toolCtx: Context) => {\n      toolCtx.tools.register(defineTool({\n        name: 'skill_search',\n        description: SKILL_SEARCH_DESCRIPTION,\n        parameters: {\n          query: {\n            type: 'string',\n            required: true,\n            description:\n              'What you need to do, in the task\\'s own words — e.g. \"extract tables from a scanned PDF invoice\".',\n          },\n        },\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              skills: { type: 'string', required: true, description: 'The matching skills, rendered.' },\n              matched: { type: 'boolean', required: true, description: 'Whether anything matched.' },\n            },\n          },\n          render: (_args, value) => [{ type: 'text', text: value.skills }],\n        },\n        async execute(args, exec) {\n          const query = String((args as { query?: unknown }).query ?? '').trim()\n          if (!query) return { skills: 'skill_search needs a query describing the task.', matched: false }\n          // `exec.agent` is optional on the host's contract — a non-agent\n          // caller has none — and `toolNames` was called twice, walking the\n          // tool registry once per branch of its own ternary.\n          const availableTools = toolNames(ctx, exec.agent)\n          try {\n            const skills = await engine.retrieve(query, {\n              signal: exec.signal,\n              ...(availableTools ? { availableTools } : {}),\n            })\n            // A miss is an answer. An empty string would read to a model as a\n            // broken tool rather than as \"the library has no fit\".\n            return skills\n              ? { skills, matched: true }\n              : { skills: `No skill in the library matches \"${query}\". Proceed without one.`, matched: false }\n          } catch {\n            // Same rule as the injection path: a failed search costs the turn a\n            // skill, not the turn.\n            return { skills: 'Skill search is unavailable right now. Proceed without a skill.', matched: false }\n          }\n        },\n      }))\n    })\n    ctx.logger('skill-search').info('on-demand mode: the agent calls skill_search')\n    return\n  }\n  ctx.logger('skill-search').info('auto mode: retrieval runs on every turn')\n\n  ctx.on('agent/pre-step', async (\n    { agent, messages, signal },\n    next,\n  ): Promise<PreStepDecision> => {\n    const decision = await next()\n    if (decision.kind === 'reject') return decision\n    const query = latestUserText(messages)\n    if (!query) return decision\n    signal.throwIfAborted()\n\n    const hits = await engine.hits(query, { signal, availableTools: toolNames(ctx, agent) })\n    if (hits.length === 0) return decision\n    const text = engine.render(hits)\n    if (!text) return decision\n    signal.throwIfAborted()\n\n    const source: SkillSearchSource = {\n      kind: 'skill-search',\n      form: 'instructions',\n      skillIds: hits.map(h => h.qualifiedId),\n    }\n    const injection: UserMessage = createUserMessage({\n      content: [{ type: 'text', text }],\n      source,\n    })\n    return { kind: 'enter', messages: [...decision.messages, injection] }\n  })\n}\n\n/**\n * Where a retrieved skill is kept, or `undefined` to use the cache.\n *\n * The shared skills directory when the deployment opted in, created here\n * rather than lazily: a directory that does not exist is not scanned, and a\n * skill installed into an unscanned directory is the exact bug this feature\n * exists to fix.\n */\nfunction installRootFor(share: boolean): string | undefined {\n  if (!share) return undefined\n  try {\n    const root = sharedSkillsDir()\n    mkdirSync(root, { recursive: true })\n    return root\n  } catch {\n    // Sharing is never worth a failed turn.\n    return undefined\n  }\n}\n\nfunction buildEngine(ctx: Context, cfg: Config): SkillSearchEngine {\n  const sources: SkillSource[] = []\n\n  const dirs = cfg.skillsDirs ?? []\n  // Registers this harness's skills directory so the other four hosts can\n  // scan it, and appends the shared directory plus whatever they registered.\n  // `?? true` because this reaches `buildEngine` through the exported\n  // `Config` type, where the field is optional — the zod default only applies\n  // to config the harness parsed. Without it the harness's own type-check\n  // fails, which is how this was found: the repository suites never compile\n  // this file against that interface.\n  const share = cfg.shareSkills ?? true\n  const installRoot = installRootFor(share)\n  const roots = scanDirs('deepseek-harness', dirs, share)\n  if (roots.length > 0) {\n    const local = new LocalSkillSource(roots, { indexBody: cfg.indexBody ?? false })\n    local.weight = cfg.weightLocal ?? 1.0\n    sources.push(local)\n  }\n\n  let client: SkillHubClient | undefined\n  if (cfg.hubEndpoint) {\n    client = new SkillHubClient(cfg.hubEndpoint, {\n      ...(installRoot ? { installRoot } : {}),\n      ...(cfg.hubApiKey ? { apiKey: cfg.hubApiKey } : {}),\n      timeoutMs: cfg.hubTimeoutMs ?? 5000,\n      // Beside the scanned directories, never inside one: an extracted\n      // bundle under a skills directory would be rescanned as a local skill.\n      cacheDir: cfg.bundleCacheDir || join(homedir(), '.dsh', 'skillsearch-bundles'),\n    })\n    sources.push(\n      new HubSkillSource(client, {\n        weight: cfg.weightHub ?? 0.85,\n        minSafety: cfg.hubMinSafety ?? 0.7,\n      }),\n    )\n  }\n\n  const marketplaceClients = new Map<string, MarketplaceClient>()\n  for (const [kind, endpoint] of [['clawhub', cfg.clawhubEndpoint], ['skillhub_cn', cfg.skillhubCnEndpoint]] as const) {\n    if (!endpoint) continue\n    const marketplace = new MarketplaceClient(kind, endpoint, {\n      ...(installRoot ? { installRoot } : {}),\n      cacheDir: cfg.bundleCacheDir || join(homedir(), '.dsh', 'skillsearch-bundles'),\n      timeoutMs: cfg.hubTimeoutMs ?? 5000,\n    })\n    marketplaceClients.set(kind, marketplace)\n    sources.push(new MarketplaceSkillSource(marketplace))\n  }\n\n  const route = resolveRoute(cfg)\n  const model = route ? modelBridge(ctx, route) : undefined\n  // Two independent switches over one model, matching the Python config.\n  // Configuring a model used to turn both on